package br.edu.ufersa.pw.todo.buggytrip.domain.service;
import br.edu.ufersa.pw.todo.buggytrip.api.dtos.Usuario.UsuarioRequest; import br.edu.ufersa.pw.todo.buggytrip.api.exceptions.ConflictException; import br.edu.ufersa.pw.todo.buggytrip.domain.enuns.EnumUsuario; import br.edu.ufersa.pw.todo.buggytrip.domain.repositories.UsuarioRepository; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.crypto.password.PasswordEncoder; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class UsuarioServiceTest{@Mock UsuarioRepository repo;@Mock PasswordEncoder encoder;UsuarioService service;@BeforeEach void setUp(){MockitoAnnotations.openMocks(this);service=new UsuarioService(repo,encoder);}@Test void criaUsuario(){var r=new UsuarioRequest("Ana","ana@test.com","Senha@123",EnumUsuario.CLIENTE);when(repo.existsByEmailIgnoreCase(r.email())).thenReturn(false);when(encoder.encode(r.senha())).thenReturn("hash");when(repo.save(any())).thenAnswer(i->i.getArgument(0));var x=service.criar(r);assertEquals("ana@test.com",x.email());assertEquals(EnumUsuario.CLIENTE,x.tipo());}@Test void rejeitaEmailDuplicado(){var r=new UsuarioRequest("Ana","ana@test.com","Senha@123",EnumUsuario.CLIENTE);when(repo.existsByEmailIgnoreCase(r.email())).thenReturn(true);assertThrows(ConflictException.class,()->service.criar(r));}}
